<header class="section-heading"><div><span class="status">Alunos</span><h1>Consultar</h1><p class="meta">Alunos ativos com cadastro financeiro, unidade e Moodle vinculados.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/finance/customers/create"><i class="fa-solid fa-user-plus"></i> Novo aluno</a></header>
<form method="get" action="<?= $escape($basePath) ?>/students" class="contact-filters"><input name="q" value="<?= $escape($search) ?>" placeholder="Nome, e-mail, CPF ou usuário do Moodle"><button type="submit">Pesquisar</button><?php if($search!==''):?><a class="button-secondary" href="<?= $escape($basePath) ?>/students">Limpar</a><?php endif;?></form>
<section class="card"><div class="table-responsive"><table><thead><tr><th>Aluno</th><th>CPF</th><th>Unidade</th><th>Moodle</th><th>Cursos ativos</th><th>Ação</th></tr></thead><tbody><?php if($students===[]):?><tr><td colspan="6">Nenhum aluno 100% vinculado encontrado.</td></tr><?php endif;?><?php foreach($students as$student):?><tr><td><strong><?= $escape($student['name']) ?></strong><br><small><?= $escape($student['email']?:'Sem e-mail') ?></small></td><td><?= $escape($student['cpf_cnpj']) ?></td><td><?= $escape($student['unit_name']) ?></td><td><span class="connection-badge connection-connected"><i class="fa-solid fa-check"></i>&nbsp; <?= $escape($student['username']) ?></span></td><td><?= (int)$student['active_courses'] ?></td><td><a class="button-secondary button-small" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$student['id'] ?>"><i class="fa-solid fa-eye"></i> Abrir</a></td></tr><?php endforeach;?></tbody></table></div></section>
